import { revalidateTag } from 'next/cache'

import { enqueueCatalogSync } from '@/lib/db'
import { getProducts } from '@/lib/products'

export default async function AdminProductsPage() {
  async function syncCatalog() {
    'use server'

    // Kick off the upstream ERP/PIM sync. This returns as soon as the job is
    // queued so the admin is not blocked on thousands of SKUs.
    await enqueueCatalogSync()

    // Mark every cache entry tagged `"products"` as stale. With `profile="max"`
    // the next reader is served the existing (possibly stale) catalog while the
    // fresh data is recomputed in the background, so the admin can keep working
    // and all catalog views converge shortly after.
    revalidateTag('products', 'max')
  }

  const products = await getProducts()

  return (
    <div>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

